259	    /**
260	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where REGION is
261	     * the region derived from the owner's postcode (preferring the postcode, falling back to the
262	     * city table, else {@code 'UNKNOWN'}; see {@link OwnerMapper#regionOf(Owner)}) and HASH8 is the
263	     * first 8 upper-case hex characters of the SHA-256 digest of the owner's normalized E.164
264	     * telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). The code carries no
265	     * sequence number, so it is a stable function of the owner's region and telephone/last-name
266	     * identity rather than of creation order.
267	     *
268	     * @param owner the owner being created, with its telephone already normalized to E.164 form
269	     * @return the assigned customer code
270	     */
271	    private String customerCodeFor(Owner owner) {
272	        String region = ownerMapper.regionOf(owner);
273	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName()).substring(0, 8);
274	        return region + "-" + hash8;
275	    }
276	
277	    /**
278	     * Computes the SHA-256 digest of the UTF-8 bytes of {@code value} and renders it as an
279	     * upper-case hex string.
280	     *
281	     * @param value the string to hash
282	     * @return the full SHA-256 digest as upper-case hex
283	     */
284	    private static String sha256UpperHex(String value) {
285	        try {
286	            byte[] digest = MessageDigest.getInstance("SHA-256")
287	                .digest(value.getBytes(StandardCharsets.UTF_8));
288	            StringBuilder sb = new StringBuilder(digest.length * 2);
289	            for (byte b : digest) {
290	                sb.append(String.format("%02X", b));
291	            }
292	            return sb.toString();
293	        } catch (NoSuchAlgorithmException ex) {
294	            throw new IllegalStateException("SHA-256 not available", ex);
295	        }
296	    }
297	
298	    /**
299	     * The maximum number of owners allowed to live in a single city. A create is rejected once the
300	     * owner's city already contains this many owners.
301	     */
302	    private static final int CITY_CAPACITY = 50;
303	
304	    /**
305	     * The maximum number of owners that may be created on a single day. A create is rejected with
306	     * {@link HttpStatus#TOO_MANY_REQUESTS} once this many owners already have today's
307	     * {@code registrationDate}.
308	     */
309	    private static final int DAILY_CREATE_LIMIT = 100;
310	
311	    /**
312	     * The number of owners that must already have been created for the current day before a new
313	     * create is flagged with {@code bulkSignupWarning}. The warning is set once more than this many
314	     * owners already carry today's {@code registrationDate}.
315	     */
316	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
317	
318	    /**
319	     * Rolls a registration date forward onto a business day: a date that falls on a Saturday or
320	     * Sunday is moved forward to the following Monday, while a date already on a weekday is returned
321	     * unchanged. Applied to the effective registration date (supplied or defaulted to the server
322	     * date) so that the stored {@code registrationDate}, and every value derived from it, always
323	     * falls on a business day.
324	     *
325	     * @param date the effective registration date
326	     * @return the same date when it is a weekday, otherwise the following Monday
327	     */
328	    private static LocalDate rollToBusinessDay(LocalDate date) {
329	        return switch (date.getDayOfWeek()) {
330	            case SATURDAY -> date.plusDays(2);
331	            case SUNDAY -> date.plusDays(1);
332	            default -> date;
333	        };
334	    }
335	
336	    /**
337	     * Counts the existing owners whose {@code registrationDate} equals the given (already
338	     * business-day-adjusted) date, i.e. the number of owners that have already been created for that
339	     * business day. Called before a new owner is saved, so the returned value reflects the number of
340	     * owners created for that day prior to this create.
341	     *
342	     * @param date the adjusted business-day registration date to count against
343	     * @return the number of existing owners registered on that date
344	     */
345	    private int countOwnersRegisteredOn(LocalDate date) {
346	        return (int) this.clinicService.findAllOwners().stream()
347	            .filter(existing -> date.equals(existing.getRegistrationDate()))
348	            .count();
349	    }
350	
351	    /**
352	     * Counts the existing owners that live in the given city, comparing city names case-insensitively.
353	     *
354	     * @param city the city to count owners for
355	     * @return the number of existing owners in that city
356	     */
357	    private int countOwnersInCity(String city) {
358	        return (int) this.clinicService.findAllOwners().stream()
359	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
360	            .count();
361	    }
