363	    /**
364	     * Builds the membership number for a new owner, formatted {@code '<customerCode>-M<YY>'} where YY is
365	     * the last two digits of the registration date's year (e.g. {@code 'NSW-1A2B3C4D-M26'}).
366	     *
367	     * @param customerCode     the owner's assigned customer code
368	     * @param registrationDate the owner's registration date
369	     * @return the assigned membership number
370	     */
371	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
372	        String yy = String.format("%02d", registrationDate.getYear() % 100);
373	        return String.format("%s-M%s", customerCode, yy);
374	    }
375	
376	    /**
377	     * Counts the existing owners that already share the given first name and last name, comparing
378	     * both case-insensitively. Called before a new owner is saved, so the returned value reflects
379	     * the number of namesakes that existed prior to this create.
380	     *
381	     * @param firstName the new owner's first name
382	     * @param lastName  the new owner's last name
383	     * @return the number of existing owners with the same first and last name
384	     */
385	    private int countNamesakes(String firstName, String lastName) {
386	        int count = 0;
387	        for (Owner existing : this.clinicService.findAllOwners()) {
388	            if (firstName.equalsIgnoreCase(existing.getFirstName())
389	                && lastName.equalsIgnoreCase(existing.getLastName())) {
390	                count++;
391	            }
392	        }
393	        return count;
394	    }
