396	    /**
397	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
398	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
399	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
400	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
401	     * string is what gets stored and returned.
402	     *
403	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
404	     *
405	     * <p>Once in E.164 form the national-number length is validated against the country code: a
406	     * {@code +61} (Australia) number must carry exactly 9 national digits and a {@code +1} (NANP)
407	     * number exactly 10 (see {@link #COUNTRY_NATIONAL_LENGTHS}). Country codes without a configured
408	     * rule are accepted on the general 8-to-15 digit length alone.
409	     *
410	     * @param telephone the raw telephone value supplied by the client
411	     * @return the normalized E.164 telephone number
412	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
413	     *                                 valid E.164 number (unexpected characters, not 8 to 15 digits
414	     *                                 after the {@code '+'}, or the wrong national-number length for
415	     *                                 its country code)
416	     */
417	    private static String normalizeTelephone(String telephone) {
418	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
419	        String digits;
420	        if (cleaned.startsWith("+")) {
421	            digits = cleaned.substring(1);
422	        } else {
423	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
424	            digits = "61" + national;
425	        }
426	        if (!digits.matches("[0-9]{8,15}")) {
427	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
428	                "telephone could not be normalized to a valid E.164 number");
429	        }
430	        validateNationalNumberLength(digits);
431	        return "+" + digits;
432	    }
433	
434	    /**
435	     * International dialling codes mapped to the exact number of national (subscriber) digits an
436	     * E.164 number for that country must carry: {@code +61} (Australia) requires 9 national digits
437	     * and {@code +1} (NANP) requires 10. Country codes absent from this map have no length rule.
438	     */
439	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
440	
441	    /**
442	     * Validates the national-number length of an E.164 number (its digits, without the leading
443	     * {@code '+'}) against its country code. The longest configured dialling code that prefixes the
444	     * number selects the rule; if none is configured the number passes (only the general 8-to-15
445	     * digit rule applies).
446	     *
447	     * @param digits the E.164 digits without the leading {@code '+'}
448	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the number of national
449	     *                                 digits does not match the country code's required length
450	     */
451	    private static void validateNationalNumberLength(String digits) {
452	        COUNTRY_NATIONAL_LENGTHS.keySet().stream()
453	            .filter(digits::startsWith)
454	            .max(Comparator.comparingInt(String::length))
455	            .ifPresent(code -> {
456	                int nationalLength = digits.length() - code.length();
457	                if (nationalLength != COUNTRY_NATIONAL_LENGTHS.get(code)) {
458	                    throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
459	                        "telephone must have " + COUNTRY_NATIONAL_LENGTHS.get(code)
460	                            + " national digits for country code +" + code);
461	                }
462	            });
463	    }
464	
465	    /**
466	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
467	     * containing at least one dot, none of the three sections containing whitespace or an
468	     * additional {@code @}.
469	     */
470	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
471	
472	    /**
473	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
474	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
475	     * value is then stored and returned lower-cased.
476	     *
477	     * @param email the raw email value supplied by the client, possibly {@code null}
478	     * @return the lower-cased email, or {@code null} when none was supplied
479	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
480	     *                                 is not a syntactically valid address
481	     */
482	    private static String normalizeEmail(String email) {
483	        if (email == null) {
484	            return null;
485	        }
486	        if (!EMAIL_PATTERN.matcher(email).matches()) {
487	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
488	                "email must be a syntactically valid address");
489	        }
490	        return email.toLowerCase(Locale.ROOT);
491	    }
