493	    /**
494	     * Fixed region-to-inclusive-postcode-range table. The postcode of an owner whose city maps to a
495	     * known region (via {@link OwnerMapper#CITY_REGION}) must fall within its region's range: NSW
496	     * 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}} inclusive.
497	     */
498	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
499	        "NSW", new int[] {2000, 2099},
500	        "VIC", new int[] {3000, 3099},
501	        "QLD", new int[] {4000, 4099});
502	
503	    /**
504	     * Validates an owner's optional postcode against the city's region. Postcode is validated only
505	     * when present ({@code null} is accepted, keeping the request contract backward-compatible). The
506	     * four-digit format is enforced by request validation; here the value is range-checked: when the
507	     * city maps to a known region (via {@link OwnerMapper#CITY_REGION}) the postcode must fall within
508	     * that region's inclusive range (see {@link #REGION_POSTCODE_RANGES}). A city with no known region
509	     * accepts any four-digit postcode.
510	     *
511	     * @param city     the owner's city
512	     * @param postcode the owner's postcode, possibly {@code null}
513	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a supplied postcode is
514	     *                                 out of range for the city's region
515	     */
516	    private static void validatePostcode(String city, String postcode) {
517	        if (postcode == null) {
518	            return;
519	        }
520	        String region = OwnerMapper.CITY_REGION.get(city);
521	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
522	        if (range == null) {
523	            return;
524	        }
525	        int value = Integer.parseInt(postcode);
526	        if (value < range[0] || value > range[1]) {
527	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
528	                "postcode " + postcode + " is not valid for region " + region);
529	        }
530	    }
531	
532	    /**
533	     * Common street-type abbreviations expanded to their full word during address normalization.
534	     * Keys and values are upper-case; matching is done per whitespace-delimited token.
535	     */
536	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
537	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
538	
539	    /**
540	     * Normalizes an owner address for storage. Leading/trailing whitespace is trimmed and internal
541	     * runs of whitespace are collapsed to a single space, the value is upper-cased, and common
542	     * street-type abbreviations are expanded per token ({@code ST -> STREET}, {@code RD -> ROAD},
543	     * {@code AVE -> AVENUE}). This normalized value is what gets stored, returned, and used for every
544	     * address comparison (household duplicate detection and the shared household id).
545	     *
546	     * <p>For example {@code "  12  main  st "} is normalized to {@code "12 MAIN STREET"}.
547	     *
548	     * @param address the raw address supplied by the client, possibly {@code null}
549	     * @return the normalized address
550	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the address is blank
551	     *                                 after normalization (required field)
552	     */
553	    private static String normalizeAddress(String address) {
554	        String collapsed = address == null ? "" : address.trim().replaceAll("\\s+", " ");
555	        if (collapsed.isEmpty()) {
556	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
557	                "address must not be blank");
558	        }
559	        String[] tokens = collapsed.toUpperCase(Locale.ROOT).split(" ");
560	        StringBuilder normalized = new StringBuilder();
561	        for (int i = 0; i < tokens.length; i++) {
562	            if (i > 0) {
563	                normalized.append(' ');
564	            }
565	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
566	        }
567	        return normalized.toString();
568	    }
569	
570	    /**
571	     * Determines whether the given whole identity key already belongs to any owner other than the
572	     * one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g. on
573	     * create). The key is derived in one place — {@link OwnerMapper#toIdentityKey(Owner)}, the same
574	     * method that builds the {@code identityKey} returned on the DTO — so the value governing the
575	     * 409 is exactly the value clients see. Only an exact full-key match counts as a duplicate.
576	     *
577	     * @param identityKey the identity key to look for
578	     * @param excludeId   id of an owner to ignore during the check, or {@code null} for none
579	     * @return {@code true} if another owner already has the same identity key
580	     */
581	    private boolean isIdentityKeyInUse(String identityKey, Integer excludeId) {
582	        for (Owner existing : this.clinicService.findAllOwners()) {
583	            if (excludeId != null && excludeId.equals(existing.getId())) {
584	                continue;
585	            }
586	            if (identityKey.equals(ownerMapper.toIdentityKey(existing))) {
587	                return true;
588	            }
589	        }
590	        return false;
591	    }
592	
593	    /**
594	     * Finds the existing owner that the given (not-a-hard-duplicate) new owner is a possible
595	     * (soft) duplicate of: one that shares the new owner's last name (compared case-insensitively)
596	     * and postcode while carrying a <em>different</em> normalized telephone. A hard duplicate
597	     * (identical identity key) has already been rejected with a 409 before this runs, so this
598	     * flags only the softer last-name/postcode overlap. The match with the lowest id is returned
599	     * so the result is deterministic when several owners qualify.
600	     *
601	     * @param owner the new owner being created, with its telephone already normalized
602	     * @return the matching existing owner, or {@code null} when none qualifies
603	     */
604	    private Owner findPossibleDuplicate(Owner owner) {
605	        if (owner.getLastName() == null || owner.getPostcode() == null) {
606	            return null;
607	        }
608	        return this.clinicService.findAllOwners().stream()
609	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
610	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
611	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
612	            .min(Comparator.comparingInt(Owner::getId))
613	            .orElse(null);
614	    }
615	
616	}
